from collections import namedtuple
from functools import wraps
from taf.internal.ue.pioneer.api.command.base import NamedTupleBeanJsonCommand, json_validate


class PioneerCommand(NamedTupleBeanJsonCommand):
    pass


def create_pioneer_namedtuple_bean(class_name, base_tags, tags_in_param, tags_in_optional_param, *values, **kw_values):

    if tags_in_optional_param:
        if set(tags_in_param[-len(tags_in_optional_param):]) != set(tags_in_optional_param):
            raise Exception("optional tags are not the continuous items at the end of tags of params")

    output_values = [class_name, ]
    if values:
        output_values.extend(values)

    all_lowercase_tags = [tag.lower() for tag in (list(base_tags) + list(tags_in_param))]
    lowercase_optional_tags = [tag.lower() for tag in tags_in_optional_param]
    lowercase_kw_values = {key.lower(): value for key, value in kw_values.items()}

    for key in all_lowercase_tags:  # compatible for < python3.7
        if key in lowercase_kw_values:
            if lowercase_kw_values[key] is not None or key not in lowercase_optional_tags:
                output_values.append(lowercase_kw_values[key])

    top_tags = ['CMD', ] + list(base_tags)
    param_property_tuple = tuple()  # noqa C408
    CMD_TAG_LEN = 1
    param_values = output_values[CMD_TAG_LEN + len(base_tags):]
    final_tags_in_param = tags_in_param[0:len(param_values)]
    if tags_in_param:
        Param = namedtuple('Param', final_tags_in_param)
        param_property = Param._make(param_values)
        param_property_tuple = (param_property,)
        top_tags = top_tags + ['Param', ]

    Bean = namedtuple('Bean', top_tags)
    bean = Bean._make(tuple(output_values[0:len(base_tags) + 1]) + param_property_tuple)
    return bean


def pioneer_request(base=None, params=None, optionals=None):
    if base is None:
        base = []

    if params is None:
        params = []

    if optionals is None:
        optionals = []

    def wrapper(cls):
        if not issubclass(cls, PioneerCommand):
            raise Exception("pioneer_request only can decorate subclass of PioneerCommand")

        def create_request_bean_decorator(func):
            @wraps(func)
            def decorated(self, *args, **kwargs):
                return create_pioneer_namedtuple_bean(cls.__name__, base, params, optionals, *args, **kwargs)

            return decorated

        setattr(cls, cls._create_request_bean.__name__, create_request_bean_decorator(cls._create_request_bean))
        # cls._create_request_bean = create_request_bean_decorator(cls._create_request_bean)
        return cls

    return wrapper


def pioneer_response(base=None, params=None, optionals=None):
    if base is None:
        base = []

    if params is None:
        params = []

    if optionals is None:
        optionals = []

    def wrapper(cls):
        if not issubclass(cls, PioneerCommand):
            raise Exception("pioneer_request only can decorate subclass of PioneerCommand")

        def create_response_bean_decorator(func):
            @wraps(func)
            def decorated(self, *args, **kwargs):
                if 'Param' in kwargs:
                    param_items = kwargs['Param']
                    kwargs.pop('Param')
                    kwargs.update(param_items)
                return create_pioneer_namedtuple_bean(cls.__name__, base, params, optionals, *args, **kwargs)

            return decorated

        setattr(cls, cls._create_response_bean.__name__, create_response_bean_decorator(cls._create_response_bean))
        return cls

    return wrapper


